'use client';
import MarketTicker from './components/MarketTicker';
import NewsCard, { NewsCardSkeleton } from './components/NewsCard';
import { InvestmentPieChart, ExpenseBarChart } from './components/Charts';
import { useState, useMemo, useEffect } from 'react';
import { Plus, AlertTriangle, TrendingUp, Wallet, Calendar, X, Target, Briefcase, PiggyBank, TrendingDown, Activity, ArrowUpRight, ArrowDownRight, BarChart3, DollarSign, Download, FileSpreadsheet, FileText, LogOut, Bell, Newspaper } from 'lucide-react';
import { supabase } from './supabase';
import { exportToExcel, exportToPDF, formatTransactionsForExport, formatGoalsForExport, formatPatrimonyForExport } from './utils/export';

const formatBRL = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
const formatUSD = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value);
const formatCurrency = (value: number, categoryName?: string) => categoryName === 'Dólar' ? formatUSD(value) : formatBRL(value);
const formatDateBR = (dateString: string) => { if (!dateString) return ''; const [y, m, d] = dateString.split('-'); return `${d}/${m}/${y}`; };
const formatMonthYear = (dateString: string) => new Date(dateString).toLocaleDateString('pt-BR', { month: 'short', year: 'numeric' });

function Card({ children, className = '', gold = false, onClick, ...rest }: any) {
  if (onClick) {
    return <button type="button" onClick={onClick} {...rest} className={`card-premium ${gold ? 'card-gold' : ''} cursor-pointer hover:shadow-lg transition-all hover:-translate-y-0.5 text-left w-full ${className}`}>{children}</button>;
  }
  return <div {...rest} className={`card-premium ${gold ? 'card-gold' : ''} ${className}`}>{children}</div>;
}

function Badge({ children, variant = 'default' }: any) {
  const s: any = { default: 'bg-slate-100 text-slate-700', realized: 'bg-green-100 text-green-800', projected: 'bg-slate-50 text-slate-600 border border-dashed border-slate-300', warning: 'bg-yellow-100 text-yellow-800', danger: 'bg-red-100 text-red-800', unexpected: 'bg-orange-100 text-orange-800', gold: 'bg-[#A9823A]/10 text-[#A9823A]', navy: 'bg-[#0B1F33]/10 text-[#0B1F33]', success: 'bg-[#2F6B57]/10 text-[#2F6B57]' };
  return <span className={`badge-premium ${s[variant]}`}>{children}</span>;
}

function ProgressBar({ value, color = 'bg-[#0B1F33]' }: any) {
  return <div className="progress-premium"><div className={`progress-premium-fill ${color}`} style={{ width: `${Math.min(value, 100)}%` }} /></div>;
}

function LoginScreen({ onLogin }: { onLogin: (user: string) => void }) {
  const [selectedUser, setSelectedUser] = useState<'Felipe' | 'Camila'>('Felipe');
  const [password, setPassword] = useState('');
  const handleLogin = () => { if (password === '1234' || password === '') { localStorage.setItem('currentUser', selectedUser); onLogin(selectedUser); } else { alert('Senha incorreta!'); } };
  return (
    <div className="min-h-screen bg-[#F7F5F0] flex items-center justify-center p-4 font-body">
      <div className="max-w-md w-full">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-[#0B1F33] rounded-2xl flex items-center justify-center mx-auto mb-4"><Wallet className="w-8 h-8 text-[#C5A45A]" /></div>
          <h1 className="font-display text-3xl font-bold text-[#0B1F33] mb-2">Finanças do Casal</h1>
          <p className="text-[#707780]">Gestão Patrimonial</p>
        </div>
        <Card className="p-6">
          <h2 className="font-display text-xl font-bold text-[#0B1F33] mb-6">Quem está acessando?</h2>
          <div className="space-y-4 mb-6">
            <button onClick={() => setSelectedUser('Felipe')} className={`w-full p-4 rounded-lg border-2 transition-all ${selectedUser === 'Felipe' ? 'border-[#0B1F33] bg-[#0B1F33]/5' : 'border-[#0B1F33]/20 hover:border-[#0B1F33]/40'}`}><div className="flex items-center gap-3"><div className="w-12 h-12 bg-[#0B1F33] rounded-full flex items-center justify-center text-white font-bold">F</div><div className="text-left"><p className="font-bold text-[#0B1F33]">Felipe</p><p className="text-xs text-[#707780]">Acessar como Felipe</p></div></div></button>
            <button onClick={() => setSelectedUser('Camila')} className={`w-full p-4 rounded-lg border-2 transition-all ${selectedUser === 'Camila' ? 'border-[#A9823A] bg-[#A9823A]/5' : 'border-[#0B1F33]/20 hover:border-[#0B1F33]/40'}`}><div className="flex items-center gap-3"><div className="w-12 h-12 bg-[#A9823A] rounded-full flex items-center justify-center text-white font-bold">C</div><div className="text-left"><p className="font-bold text-[#0B1F33]">Camila</p><p className="text-xs text-[#707780]">Acessar como Camila</p></div></div></button>
          </div>
          <div className="space-y-2 mb-6"><label className="text-sm font-medium text-[#0B1F33]">Senha (opcional)</label><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="1234 ou deixe vazio" className="w-full rounded-lg border border-[#0B1F33]/20 px-3 py-2 text-sm bg-[#F7F5F0]" /></div>
          <button onClick={handleLogin} className="w-full bg-[#0B1F33] hover:bg-[#172a3d] text-white font-semibold py-3 rounded-lg transition-colors border border-[#A9823A]/30">Entrar</button>
        </Card>
      </div>
    </div>
  );
}

export default function FinanceDashboard() {
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [categories, setCategories] = useState<any[]>([]);
  const [budgets, setBudgets] = useState<any[]>([]);
  const [goals, setGoals] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [goalContributions, setGoalContributions] = useState<any[]>([]);
  const [assets, setAssets] = useState<any[]>([]);
  const [liabilities, setLiabilities] = useState<any[]>([]);
  const [patrimonyHistory, setPatrimonyHistory] = useState<any[]>([]);
  const [cashFlowHistory, setCashFlowHistory] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [useMockData, setUseMockData] = useState(false);
  const [activeTab, setActiveTab] = useState<any>('dashboard');
  const [patrimonyView, setPatrimonyView] = useState<'family' | 'Felipe' | 'Camila'>('family');
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [viewFilter, setViewFilter] = useState<any>('all');
  const [userFilter, setUserFilter] = useState<any>('all');
  const [selectedMonth, setSelectedMonth] = useState(() => { const n = new Date(); return `${n.getFullYear()}-${String(n.getMonth() + 1).padStart(2, '0')}`; });
  const [editingTransaction, setEditingTransaction] = useState<any>(null);
  const [recurringTemplates, setRecurringTemplates] = useState<any[]>([]);
  const [news, setNews] = useState<any[]>([]);
  const [newsLoading, setNewsLoading] = useState(true);
  const [newsSource, setNewsSource] = useState<any>('all');
  const [isListening, setIsListening] = useState(false);
  const [voiceTranscript, setVoiceTranscript] = useState('');
  const [formData, setFormData] = useState<any>({ created_by: 'Felipe', type: 'despesa_variavel', category_id: '', amount: '', date: new Date().toISOString().slice(0, 10), description: '', status: 'realized', is_unexpected: false, goal_title: '', goal_target: '', goal_start: new Date().toISOString().slice(0, 10), goal_end: '', is_recurring: false, recurring_day: '', recurring_end_date: '' });

  const generateRecurringForMonth = async () => {
    if (useMockData) return;
    try {
      const { data: templates } = await supabase.from('recurring_templates').select('*').eq('is_active', true);
      if (!templates || templates.length === 0) return;
      const [year, month] = selectedMonth.split('-');
      for (const t of templates) {
        const ds = `${year}-${month}-${String(t.day_of_month).padStart(2, '0')}`;
        const { data: ex } = await supabase.from('transactions').select('id').eq('date', ds).eq('category_id', t.category_id).eq('is_recurring', true).limit(1);
        if (!ex || ex.length === 0) await supabase.from('transactions').insert({ created_by: t.created_by, date: ds, amount: t.amount, type: t.type, category_id: t.category_id, status: 'projected', is_unexpected: false, description: t.description, is_recurring: true, recurring_day: t.day_of_month });
      }
    } catch (e) { console.error(e); }
  };

  const generateCashFlowHistory = async () => {
    if (useMockData) return;
    try {
      const months = [...new Set(transactions.map((t: any) => t.date?.slice(0, 7)).filter(Boolean))].sort() as string[];
      for (const m of months) {
        const mt = transactions.filter((t: any) => t.date?.startsWith(m));
        const inc = mt.filter((t: any) => t.type === 'receita' && t.status === 'realized').reduce((s: number, t: any) => s + Number(t.amount), 0);
        const exp = mt.filter((t: any) => (t.type === 'despesa_fixa' || t.type === 'despesa_variavel' || t.type === 'reserva') && t.status === 'realized').reduce((s: number, t: any) => s + Number(t.amount), 0);
        const con = mt.filter((t: any) => t.type === 'investimento' && t.status === 'realized').reduce((s: number, t: any) => s + Number(t.amount), 0);
        const { data: ex } = await supabase.from('cash_flow_history').select('id').eq('month', m).limit(1);
        if (ex && ex.length > 0) await supabase.from('cash_flow_history').update({ income: inc, expenses: exp, contributions: con }).eq('month', m);
        else await supabase.from('cash_flow_history').insert({ month: m, income: inc, expenses: exp, contributions: con });
      }
      const { data: h } = await supabase.from('cash_flow_history').select('*').order('month', { ascending: true });
      setCashFlowHistory(h || []);
    } catch (e) { console.error(e); }
  };

  const loadData = async () => {
    setLoading(true);
    try {
      const { data: c, error: ce } = await supabase.from('categories').select('*');
      if (ce) { setCategories([]); setUseMockData(true); }
      else {
        setCategories(c || []);
        const { data: b } = await supabase.from('category_budgets').select('*'); setBudgets(b || []);
        const { data: g } = await supabase.from('goals').select('*'); setGoals(g || []);
        const { data: t } = await supabase.from('transactions').select('*').order('date', { ascending: false }); setTransactions(t || []);
        const { data: gc } = await supabase.from('goal_contributions').select('*'); setGoalContributions(gc || []);
        const { data: a } = await supabase.from('assets').select('*'); setAssets(a || []);
        const { data: l } = await supabase.from('liabilities').select('*'); setLiabilities(l || []);
        const { data: ph } = await supabase.from('patrimony_history').select('*').order('month', { ascending: true }); setPatrimonyHistory(ph || []);
        const { data: cf } = await supabase.from('cash_flow_history').select('*').order('month', { ascending: true }); setCashFlowHistory(cf || []);
        setUseMockData(false);
      }
    } catch (e) { setUseMockData(true); }
    setLoading(false);
    setTimeout(() => generateRecurringForMonth(), 1000);
    setTimeout(() => generateCashFlowHistory(), 1500);
  };

  useEffect(() => { const u = localStorage.getItem('currentUser'); if (u) setCurrentUser(u); }, []);
  useEffect(() => { if (currentUser) loadData(); }, [currentUser]);

  const handleLogin = (u: string) => { setCurrentUser(u); setFormData((p: any) => ({ ...p, created_by: u })); };
  const handleLogout = () => { localStorage.removeItem('currentUser'); setCurrentUser(null); };

  const monthlyTransactions = transactions.filter((t: any) => t.date && t.date.startsWith(selectedMonth));
  const filteredTransactions = useMemo(() => monthlyTransactions.filter((t: any) => { if (viewFilter !== 'all' && t.status !== viewFilter) return false; if (userFilter !== 'all' && t.created_by !== userFilter) return false; return true; }).sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime()), [monthlyTransactions, viewFilter, userFilter]);

  const metrics = useMemo(() => {
    const realizedIncome = monthlyTransactions.filter((t: any) => t.type === 'receita' && (t.status === 'realized' || t.status === 'projected')).reduce((s: number, t: any) => s + Number(t.amount), 0);
    const realizedExpenses = monthlyTransactions.filter((t: any) => (t.type === 'despesa_fixa' || t.type === 'despesa_variavel' || t.type === 'reserva') && t.status === 'realized').reduce((s: number, t: any) => s + Number(t.amount), 0);
    const unexpectedExpenses = monthlyTransactions.filter((t: any) => t.is_unexpected && t.status === 'realized').reduce((s: number, t: any) => s + Number(t.amount), 0);
    const investments = monthlyTransactions.filter((t: any) => t.type === 'investimento' && t.status === 'realized');
    const totalAportes = investments.reduce((s: number, t: any) => s + Number(t.amount), 0);
    const monthlyYield = investments.reduce((s: number, t: any) => s + (Number(t.yield_amount) || 0), 0);
    const investmentTotals = { acoes: investments.filter((t: any) => categories.find((c: any) => c.id === t.category_id)?.name === 'Ações').reduce((s: number, t: any) => s + Number(t.amount), 0), fiis: investments.filter((t: any) => categories.find((c: any) => c.id === t.category_id)?.name === 'FIIs').reduce((s: number, t: any) => s + Number(t.amount), 0), dolar: investments.filter((t: any) => categories.find((c: any) => c.id === t.category_id)?.name === 'Dólar').reduce((s: number, t: any) => s + Number(t.amount), 0) };
    const saldo = realizedIncome - realizedExpenses;
    return { realizedIncome, realizedExpenses, unexpectedExpenses, totalAportes, saldo, saldoDisponivel: saldo - totalAportes, investmentTotals, investments, monthlyYield };
  }, [monthlyTransactions, categories]);

  const flowMetrics = useMemo(() => {
    const cm = cashFlowHistory[cashFlowHistory.length - 1]; const pm = cashFlowHistory[cashFlowHistory.length - 2];
    if (!cm) return { income: 0, expenses: 0, contributions: 0, incomeChange: 0, expensesChange: 0, contributionsChange: 0, balance: 0, history: [] };
    return { income: cm.income, expenses: cm.expenses, contributions: cm.contributions, balance: cm.income - cm.expenses - cm.contributions, incomeChange: pm ? ((cm.income - pm.income) / pm.income) * 100 : 0, expensesChange: pm ? ((cm.expenses - pm.expenses) / pm.expenses) * 100 : 0, contributionsChange: pm ? ((cm.contributions - pm.contributions) / pm.contributions) * 100 : 0, history: cashFlowHistory };
  }, [cashFlowHistory]);

  const goalsWithProgress = useMemo(() => goals.map((g: any) => { const c = goalContributions.filter((x: any) => x.goal_id === g.id); const ta = c.filter((x: any) => x.contribution_type === 'aporte').reduce((s: number, x: any) => s + Number(x.amount), 0); const tr = c.filter((x: any) => x.contribution_type === 'rendimento').reduce((s: number, x: any) => s + Number(x.amount), 0); const tac = ta + tr; return { ...g, totalAportes: ta, totalRendimentos: tr, totalAcumulado: tac, percentage: g.target_amount > 0 ? (tac / g.target_amount) * 100 : 0, remaining: g.target_amount - tac }; }), [goals, goalContributions]);

  const patrimonyMetrics = useMemo(() => { const fa = patrimonyView === 'family' ? assets : assets.filter((a: any) => a.owner === patrimonyView || a.owner === 'família'); const fl = patrimonyView === 'family' ? liabilities : liabilities.filter((l: any) => l.owner === patrimonyView || l.owner === 'família'); const ta = fa.reduce((s: number, a: any) => s + Number(a.value), 0); const tl = fl.reduce((s: number, l: any) => s + Number(l.value), 0); return { totalAssets: ta, totalLiabilities: tl, netPatrimony: ta - tl, patrimonyChange: 0 }; }, [assets, liabilities, patrimonyView]);

  const healthMetrics = useMemo(() => {
    const er = metrics.realizedIncome > 0 ? (metrics.realizedExpenses / metrics.realizedIncome) * 100 : 0;
    const ir = metrics.realizedIncome > 0 ? (metrics.totalAportes / metrics.realizedIncome) * 100 : 0;
    const hef = assets.some((a: any) => a.asset_type === 'reserva' && a.value >= 10000);
    const dr = patrimonyMetrics.totalAssets > 0 ? (patrimonyMetrics.totalLiabilities / patrimonyMetrics.totalAssets) * 100 : 0;
    const gp = goalsWithProgress.length > 0 ? goalsWithProgress.reduce((s: number, g: any) => s + g.percentage, 0) / goalsWithProgress.length : 0;
    let hs = 0; const issues: string[] = []; const strengths: string[] = [];
    if (er <= 60) hs += 25; else if (er <= 80) hs += 15; else { hs += 5; issues.push('Despesas > 80% da renda'); }
    if (ir >= 20) hs += 25; else if (ir >= 10) hs += 15; else { hs += 5; issues.push('Aportes < 10%'); }
    if (hef) { hs += 20; strengths.push('Reserva constituída'); } else issues.push('Reserva insuficiente');
    if (dr <= 30) { hs += 15; strengths.push('Endividamento saudável'); } else if (dr <= 50) { hs += 8; issues.push('Endividamento moderado'); } else { hs += 3; issues.push('Endividamento elevado'); }
    if (gp >= 50) { hs += 15; strengths.push('Metas em progresso'); } else if (gp >= 25) hs += 8; else { hs += 3; issues.push('Metas com baixo progresso'); }
    const st = hs >= 70 ? 'green' : hs >= 40 ? 'yellow' : 'red';
    const sl = hs >= 70 ? 'Equilibrada' : hs >= 40 ? 'Atenção' : 'Crítica';
    return { expenseRatio: er, investmentRatio: ir, hasEmergencyFund: hef, debtRatio: dr, goalsProgress: gp, healthStatus: st, healthLabel: sl, healthScore: hs, issues, strengths };
  }, [metrics, assets, patrimonyMetrics, goalsWithProgress]);

  const budgetStatus = useMemo(() => budgets.map((b: any) => { const cat = categories.find((c: any) => c.id === b.category_id); const spent = monthlyTransactions.filter((t: any) => t.category_id === b.category_id && t.status === 'realized' && (t.type === 'despesa_fixa' || t.type === 'despesa_variavel')).reduce((s: number, t: any) => s + Number(t.amount), 0); const lim = Number(b.monthly_limit); const pct = lim > 0 ? (spent / lim) * 100 : 0; let al = 'normal'; let ab: any = null; if (pct >= 100) { al = 'ultrapassado'; ab = 'Ultrapassado'; } else if (pct >= 85) { al = 'proximo'; ab = 'Limite Próximo'; } else if (pct >= 70) { al = 'atencao'; ab = 'Atenção'; } return { category: cat, spent, limit: lim, percentage: pct, alertLevel: al, alertBadge: ab, remaining: Math.max(0, lim - spent) }; }), [budgets, categories, monthlyTransactions]);

  useEffect(() => { if (budgetStatus.length > 0) { const a = budgetStatus.filter((b: any) => b.alertLevel === 'ultrapassado' || b.alertLevel === 'proximo').map((b: any) => ({ id: b.category?.id, message: `${b.category?.name}: ${b.alertBadge} (${b.percentage.toFixed(0)}%)`, level: b.alertLevel })); setNotifications(a); } }, [budgetStatus]);

  const handleExportTransactionsExcel = () => exportToExcel(formatTransactionsForExport(filteredTransactions, categories), `transacoes_${selectedMonth}`, 'Transações');
  const handleExportTransactionsPDF = () => exportToPDF(formatTransactionsForExport(filteredTransactions, categories), `transacoes_${selectedMonth}`, 'Relatório');
  const handleExportGoalsExcel = () => exportToExcel(formatGoalsForExport(goalsWithProgress), `metas_${selectedMonth}`, 'Metas');
  const handleExportGoalsPDF = () => exportToPDF(formatGoalsForExport(goalsWithProgress), `metas_${selectedMonth}`, 'Metas');
  const handleExportPatrimonyExcel = () => exportToExcel(formatPatrimonyForExport(assets, liabilities), `patrimonio_${selectedMonth}`, 'Patrimônio');
  const handleExportPatrimonyPDF = () => exportToPDF(formatPatrimonyForExport(assets, liabilities), `patrimonio_${selectedMonth}`, 'Patrimônio');

  const startVoiceRecognition = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) { alert('Use Chrome ou Edge.'); return; }
    const SR = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
    const r = new SR(); r.lang = 'pt-BR'; r.continuous = false; r.interimResults = false;
    r.onstart = () => setIsListening(true); r.onend = () => setIsListening(false);
    r.onresult = (e: any) => { const tr = e.results[0][0].transcript.toLowerCase(); setVoiceTranscript(tr); let da = '', dc = '', dt = 'despesa_variavel'; const am = tr.match(/(\d+[.,]?\d*)\s*(reais|real|r\$|rs)/i) || tr.match(/(r\$|rs)\s*(\d+[.,]?\d*)/i) || tr.match(/\b(\d+[.,]?\d{2})\b/); if (am) da = (am[2] || am[1]).replace(',', '.'); if (tr.includes('receita') || tr.includes('ganhei') || tr.includes('salário')) dt = 'receita'; else if (tr.includes('investimento') || tr.includes('aporte')) dt = 'investimento'; const cm: Record<string, string> = { 'mercado': 'c17', 'uber': 'c21', 'gasolina': 'c21', 'restaurante': 'c22', 'ifood': 'c22', 'luz': 'c9', 'internet': 'c12', 'aluguel': 'c7', 'farmácia': 'c18', 'lazer': 'c23', 'vestuário': 'c24', 'pet': 'c26', 'cartão': 'c27', 'ações': 'c29', 'fii': 'c30', 'dólar': 'c32', 'bitcoin': 'c33', 'reserva': 'c36', 'viagem': 'c37' }; for (const [k, v] of Object.entries(cm)) { if (tr.includes(k)) { dc = v; break; } } setFormData((p: any) => ({ ...p, type: dt, amount: da || p.amount, description: tr.charAt(0).toUpperCase() + tr.slice(1), category_id: dc || p.category_id })); };
    r.onerror = () => { setIsListening(false); alert('Não entendi.'); }; r.start();
  };

  const handleAddTransaction = async (e: any) => { e.preventDefault(); if (!formData.category_id) { alert('Selecione categoria!'); return; } const today = new Date().toISOString().slice(0, 10); const as = formData.date > today ? 'projected' : (formData.status || 'realized'); try { await supabase.from('transactions').insert({ created_by: formData.created_by, date: formData.date, amount: parseFloat(formData.amount), type: formData.type, category_id: formData.category_id, status: as, is_unexpected: formData.is_unexpected, description: formData.description }); await loadData(); } catch (er: any) { alert(`Erro: ${er?.message}`); return; } setIsDrawerOpen(false); setFormData({ ...formData, amount: '', description: '', category_id: '' }); };
  const handleAddGoal = async (e: any) => { e.preventDefault(); if (!formData.goal_title || !formData.goal_target) { alert('Preencha nome e valor!'); return; } try { await supabase.from('goals').insert({ title: formData.goal_title, target_amount: parseFloat(formData.goal_target), current_amount: 0, start_date: formData.goal_start, end_date: formData.goal_end || null }); await loadData(); } catch (er: any) { alert(`Erro: ${er.message}`); return; } setFormData({ ...formData, goal_title: '', goal_target: '', goal_end: '' }); setIsDrawerOpen(false); };
  const confirmTransaction = async (id: string) => { try { await supabase.from('transactions').update({ status: 'realized' }).eq('id', id); await loadData(); } catch (e) { console.error(e); } };
  const handleEditTransaction = (t: any) => { setEditingTransaction(t); setFormData({ created_by: t.created_by, type: t.type, category_id: t.category_id, amount: t.amount, date: t.date, description: t.description || '', status: t.status, is_unexpected: t.is_unexpected || false, is_recurring: t.is_recurring || false, recurring_day: t.recurring_day || '', recurring_end_date: '', goal_title: '', goal_target: '', goal_start: new Date().toISOString().slice(0, 10), goal_end: '' }); setIsDrawerOpen(true); };
  const handleDeleteTransaction = async (id: string) => { if (!confirm('Excluir?')) return; try { await supabase.from('transactions').delete().eq('id', id); await loadData(); } catch (e) { alert('Erro ao excluir'); } };
  const handleUpdateTransaction = async (e: any) => { e.preventDefault(); if (!formData.category_id) { alert('Selecione categoria!'); return; } try { await supabase.from('transactions').update({ created_by: formData.created_by, date: formData.date, amount: parseFloat(formData.amount), type: formData.type, category_id: formData.category_id, status: formData.status, is_unexpected: formData.is_unexpected, description: formData.description, is_recurring: formData.is_recurring || false, recurring_day: formData.recurring_day || null }).eq('id', editingTransaction.id); await loadData(); setEditingTransaction(null); setIsDrawerOpen(false); } catch (er: any) { alert(`Erro: ${er?.message}`); } };
  const handleCreateRecurring = async (e: any) => { e.preventDefault(); if (!formData.category_id || !formData.recurring_day) { alert('Preencha categoria e dia!'); return; } try { await supabase.from('recurring_templates').insert({ created_by: formData.created_by, type: formData.type, category_id: formData.category_id, amount: parseFloat(formData.amount), description: formData.description, day_of_month: parseInt(formData.recurring_day), end_date: formData.recurring_end_date || null, is_active: true }); await supabase.from('transactions').insert({ created_by: formData.created_by, date: `${selectedMonth}-${String(formData.recurring_day).padStart(2, '0')}`, amount: parseFloat(formData.amount), type: formData.type, category_id: formData.category_id, status: 'projected', is_unexpected: false, description: formData.description, is_recurring: true, recurring_day: parseInt(formData.recurring_day) }); await loadData(); setIsDrawerOpen(false); alert('Recorrência criada!'); } catch (er: any) { alert(`Erro: ${er?.message}`); } };
  const fetchNews = async (source = 'all') => { try { setNewsLoading(true); const r = await fetch(`/api/news?source=${source}`); if (!r.ok) throw new Error('fail'); setNews(await r.json()); } catch (e) { console.error(e); } finally { setNewsLoading(false); } };
  useEffect(() => { if (activeTab === 'news') fetchNews(newsSource); }, [activeTab, newsSource]);

  const availableCategories = categories.filter((c: any) => c.type === formData.type);
  const expensesByCategory = useMemo(() => categories.filter((c: any) => c.type === 'despesa_fixa' || c.type === 'despesa_variavel').map((cat: any) => ({ name: cat.name, value: monthlyTransactions.filter((t: any) => t.category_id === cat.id && t.status === 'realized' && (t.type === 'despesa_fixa' || t.type === 'despesa_variavel')).reduce((s: number, t: any) => s + Number(t.amount), 0) })).filter((i: any) => i.value > 0).sort((a: any, b: any) => b.value - a.value).slice(0, 8), [categories, monthlyTransactions]);

  const tips = [ { title: 'Regra 50/30/20', text: '50% necessidades, 30% desejos, 20% investimentos.' }, { title: 'Reserva de Emergência', text: 'Mantenha 6 meses de despesas em Tesouro Selic.' }, { title: 'Consistência', text: 'R$ 500/mês é melhor que R$ 3.000 uma vez.' }, { title: 'Assinaturas', text: 'Revise mensalmente. Cancele o que não usa.' }, { title: 'Automatize', text: 'Programe aportes no dia do salário.' }, { title: 'Comunicação', text: 'Casais que falam de dinheiro têm menos conflitos.' }, { title: 'Metas SMART', text: 'Específicas, Mensuráveis, Alcançáveis, Relevantes, com Tempo.' } ];
  const todayTip = tips[new Date().getDate() % tips.length];

  if (!currentUser) return <LoginScreen onLogin={handleLogin} />;
  if (loading) return <div className="min-h-screen bg-[#F7F5F0] flex items-center justify-center"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#A9823A]" /></div>;

  return (
    <div className="min-h-screen bg-[#F7F5F0] pb-24 font-body">
      {notifications.length > 0 && <div className="fixed top-20 right-4 z-50 space-y-2 max-w-xs">{notifications.map((n: any) => <div key={n.id} className={`p-3 rounded-lg shadow-lg border ${n.level === 'ultrapassado' ? 'bg-[#A94B4B] text-white border-[#A94B4B]' : 'bg-[#B8860B] text-white border-[#B8860B]'}`}><div className="flex items-center gap-2"><Bell className="w-4 h-4 flex-shrink-0" /><span className="text-sm font-medium">{n.message}</span></div></div>)}</div>}
      <header className="sticky top-0 z-50 bg-[#F7F5F0] border-b border-[#0B1F33]/10 px-6 py-4 shadow-sm">
        <div className="max-w-5xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3"><div className="w-10 h-10 bg-[#0B1F33] rounded-lg flex items-center justify-center"><Wallet className="w-5 h-5 text-[#C5A45A]" /></div><div><h1 className="font-display text-xl font-bold text-[#0B1F33]">Finanças do Casal</h1><p className="text-xs text-[#707780]">Olá, {currentUser}! 👋</p></div></div>
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-2 bg-white px-3 py-2 rounded-lg border border-[#0B1F33]/10"><Calendar className="w-4 h-4 text-[#707780]" /><input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="text-sm bg-transparent outline-none text-[#0B1F33] font-medium" /></div>
              <div className="relative"><button onClick={() => setShowExportMenu(!showExportMenu)} className="p-2 bg-white rounded-lg border border-[#0B1F33]/10 hover:bg-[#0B1F33]/5"><Download className="w-4 h-4 text-[#0B1F33]" /></button>{showExportMenu && (<><div className="fixed inset-0 z-40" onClick={() => setShowExportMenu(false)} /><div className="absolute right-0 top-12 w-56 bg-white rounded-lg shadow-xl border border-[#0B1F33]/10 p-2 z-50"><p className="text-[10px] font-bold text-[#707780] uppercase px-2 py-1">Transações</p><button onClick={() => { handleExportTransactionsExcel(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileSpreadsheet className="w-4 h-4 text-[#2F6B57]" /> Excel</button><button onClick={() => { handleExportTransactionsPDF(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileText className="w-4 h-4 text-[#A94B4B]" /> PDF</button><p className="text-[10px] font-bold text-[#707780] uppercase px-2 py-1 mt-1">Metas</p><button onClick={() => { handleExportGoalsExcel(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileSpreadsheet className="w-4 h-4 text-[#2F6B57]" /> Excel</button><button onClick={() => { handleExportGoalsPDF(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileText className="w-4 h-4 text-[#A94B4B]" /> PDF</button><p className="text-[10px] font-bold text-[#707780] uppercase px-2 py-1 mt-1">Patrimônio</p><button onClick={() => { handleExportPatrimonyExcel(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileSpreadsheet className="w-4 h-4 text-[#2F6B57]" /> Excel</button><button onClick={() => { handleExportPatrimonyPDF(); setShowExportMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-[#F7F5F0] rounded"><FileText className="w-4 h-4 text-[#A94B4B]" /> PDF</button></div></>)}</div>
              <button onClick={handleLogout} className="p-2 bg-white rounded-lg border border-[#0B1F33]/10 hover:bg-[#A94B4B]/10"><LogOut className="w-4 h-4 text-[#A94B4B]" /></button>
            </div>
          </div>
          <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">{[{ id: 'dashboard', label: 'Início', icon: Wallet }, { id: 'flow', label: 'Fluxo', icon: BarChart3 }, { id: 'health', label: 'Saúde', icon: Activity }, { id: 'goals', label: 'Metas', icon: Target }, { id: 'investments', label: 'Investimentos', icon: Briefcase }, { id: 'patrimony', label: 'Patrimônio', icon: PiggyBank }, { id: 'news', label: 'Notícias', icon: Newspaper }].map((tab) => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all ${activeTab === tab.id ? 'bg-[#0B1F33] text-white shadow-md' : 'bg-white text-[#707780] hover:bg-[#0B1F33]/5 border border-[#0B1F33]/5'}`}><tab.icon className="w-4 h-4" />{tab.label}</button>)}</div>
        </div>
      </header>
      <MarketTicker />
      <main className="max-w-5xl mx-auto p-6 space-y-6 animate-fade-in">

        {activeTab === 'dashboard' && (<>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <Card className="p-5" onClick={() => setActiveTab('flow')}><div className="flex justify-between items-start"><p className="text-xs text-[#707780] font-medium uppercase">Receitas</p>{flowMetrics.incomeChange !== 0 && <span className={`text-xs font-semibold ${flowMetrics.incomeChange >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{flowMetrics.incomeChange >= 0 ? '↑' : '↓'}{Math.abs(flowMetrics.incomeChange).toFixed(0)}%</span>}</div><p className="text-2xl font-bold text-[#2F6B57] mt-2 font-display">{formatBRL(metrics.realizedIncome)}</p><p className="text-xs text-[#2F6B57] mt-2 flex items-center gap-1">Ver fluxo <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card>
            <Card className="p-5" onClick={() => setActiveTab('flow')}><div className="flex justify-between items-start"><p className="text-xs text-[#707780] font-medium uppercase">Despesas</p>{flowMetrics.expensesChange !== 0 && <span className={`text-xs font-semibold ${flowMetrics.expensesChange <= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{flowMetrics.expensesChange <= 0 ? '↓' : '↑'}{Math.abs(flowMetrics.expensesChange).toFixed(0)}%</span>}</div><p className="text-2xl font-bold text-[#A94B4B] mt-2 font-display">{formatBRL(metrics.realizedExpenses)}</p>{metrics.unexpectedExpenses > 0 && <p className="text-xs text-[#B8860B] mt-1 flex items-center gap-1"><AlertTriangle className="w-3 h-3" />{formatBRL(metrics.unexpectedExpenses)}</p>}<p className="text-xs text-[#A94B4B] mt-2 flex items-center gap-1">Ver fluxo <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card>
            <Card className="p-5" onClick={() => setActiveTab('health')}><p className="text-xs text-[#707780] font-medium uppercase">Saldo</p><p className={`text-2xl font-bold mt-2 font-display ${metrics.saldo >= 0 ? 'text-[#0B1F33]' : 'text-[#A94B4B]'}`}>{formatBRL(metrics.saldo)}</p><p className="text-xs text-[#0B1F33] mt-2 flex items-center gap-1">Ver saúde <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card>
            <Card className="p-5" onClick={() => setActiveTab('health')}><p className="text-xs text-[#707780] font-medium uppercase">Saldo Disponível</p><p className={`text-2xl font-bold mt-2 font-display ${metrics.saldoDisponivel >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{formatBRL(metrics.saldoDisponivel)}</p><p className="text-xs text-[#2F6B57] mt-2 flex items-center gap-1">Ver saúde <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Card className="p-5" onClick={() => setActiveTab('investments')}><div className="flex items-center gap-2 mb-3"><TrendingUp className="w-5 h-5 text-[#A9823A]" /><h3 className="font-display font-bold text-[#0B1F33]">Aportes do Mês</h3></div><p className="text-3xl font-bold text-[#0B1F33] font-display">{formatBRL(metrics.totalAportes)}</p><div className="flex gap-3 mt-4 text-xs text-[#707780]"><span>Ações: {formatBRL(metrics.investmentTotals.acoes)}</span><span>•</span><span>FIIs: {formatBRL(metrics.investmentTotals.fiis)}</span><span>•</span><span>USD: {formatUSD(metrics.investmentTotals.dolar)}</span></div><p className="text-xs text-[#A9823A] mt-3 flex items-center gap-1">Ver detalhes <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card>
            <Card className="p-5" onClick={() => setActiveTab('investments')}><div className="flex items-center gap-2 mb-3"><Briefcase className="w-5 h-5 text-[#A9823A]" /><h3 className="font-display font-bold text-[#0B1F33]">Total Investido</h3></div><p className="text-3xl font-bold text-[#0B1F33] font-display">{formatBRL(metrics.totalAportes)}</p><p className="text-xs text-[#707780] mt-2">{metrics.investments.length} aportes no mês</p></Card>
          </div>
          {expensesByCategory.length > 0 && <div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-4">📊 Despesas por Categoria</h3><ExpenseBarChart data={expensesByCategory} /></Card><Card className="p-6 bg-gradient-to-br from-[#0B1F33] to-[#172a3d] text-white"><h3 className="font-display font-bold text-white mb-4 flex items-center gap-2"><span className="text-2xl">💡</span> Dica Financeira</h3><p className="text-[#C5A45A] font-semibold text-sm uppercase tracking-wider mb-2">{todayTip.title}</p><p className="text-white/90 text-sm leading-relaxed">{todayTip.text}</p><div className="mt-6 pt-4 border-t border-white/10"><p className="text-white/50 text-xs">Score: {healthMetrics.healthScore}/100 — {healthMetrics.healthLabel}</p></div></Card></div>}
          <Card className="p-5"><div className="flex items-center gap-2 mb-4"><AlertTriangle className="w-5 h-5 text-[#0B1F33]" /><h3 className="font-display font-bold text-[#0B1F33]">Tetos de Gastos</h3></div>{budgetStatus.length === 0 ? <p className="text-sm text-[#707780] py-4 text-center">Nenhum teto configurado.</p> : <div className="space-y-4">{budgetStatus.map((b: any, i: number) => <div key={i} className="p-4 rounded-lg bg-[#0B1F33] text-white shadow-sm"><div className="flex justify-between items-center mb-3"><span className="font-medium text-white text-lg">{b.category?.name}</span><div className="flex items-center gap-3">{b.alertBadge && <span className={`badge-premium ${b.alertLevel === 'ultrapassado' ? 'bg-[#A94B4B] text-white' : b.alertLevel === 'proximo' ? 'bg-[#B8860B] text-white' : 'bg-[#C5A45A] text-white'}`}>{b.alertBadge}</span>}<span className="text-sm text-white/80 font-medium">{formatBRL(b.spent)} / {formatBRL(b.limit)}</span></div></div><div className="h-2 w-full bg-white/20 rounded-full overflow-hidden mb-2"><div className="h-full bg-white rounded-full transition-all" style={{ width: `${Math.min(b.percentage, 100)}%` }} /></div><div className="flex justify-between mt-2 text-xs text-white/70"><span>{b.percentage.toFixed(0)}% utilizado</span><span>{b.alertLevel !== 'ultrapassado' ? `Restam ${formatBRL(b.remaining)}` : `Ultrapassou ${formatBRL(b.spent - b.limit)}`}</span></div></div>)}</div>}</Card>
          <Card className="p-5"><div className="flex justify-between items-center mb-4"><h3 className="font-display font-bold text-[#0B1F33]">Lançamentos</h3><div className="flex gap-2">{(['all', 'Felipe', 'Camila'] as const).map((u) => <button key={u} onClick={() => setUserFilter(u)} className={`px-3 py-1 rounded-full text-xs font-medium ${userFilter === u ? 'bg-[#0B1F33] text-white' : 'bg-[#F7F5F0] text-[#707780]'}`}>{u === 'all' ? 'Todos' : u}</button>)}</div></div>{filteredTransactions.length === 0 ? <p className="text-center text-[#707780] py-8 text-sm">Nenhum lançamento neste mês.</p> : <div className="space-y-3">{filteredTransactions.map((t: any) => { const cat = categories.find((c: any) => c.id === t.category_id); return <div key={t.id} className="flex justify-between items-center p-4 bg-[#F7F5F0] rounded-lg group"><div className="flex items-center gap-3 flex-1 min-w-0"><div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0 ${t.created_by === 'Felipe' ? 'bg-[#0B1F33] text-white' : 'bg-[#A9823A] text-white'}`}>{t.created_by[0]}</div><div className="min-w-0"><div className="flex items-center gap-2"><p className="font-medium text-sm text-[#0B1F33] truncate">{t.description || cat?.name}</p>{t.is_recurring && <span className="text-xs bg-[#A9823A]/10 text-[#A9823A] px-1.5 py-0.5 rounded flex-shrink-0">🔄</span>}</div><p className="text-xs text-[#707780]">{formatDateBR(t.date)} • {cat?.name}</p></div></div><div className="flex items-center gap-2 flex-shrink-0 ml-2"><p className={`font-bold font-display text-sm ${t.type === 'receita' ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{t.type === 'receita' ? '+' : '-'} {formatCurrency(Number(t.amount), cat?.name)}</p>{t.status === 'projected' && <button onClick={() => confirmTransaction(t.id)} className="text-xs bg-white border border-[#0B1F33]/20 px-2 py-1 rounded text-[#0B1F33] hover:bg-[#0B1F33]/5">Efetivar</button>}<button onClick={() => handleEditTransaction(t)} className="p-1.5 hover:bg-[#0B1F33]/10 rounded-lg" title="Editar"><svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 text-[#0B1F33]" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button><button onClick={() => handleDeleteTransaction(t.id)} className="p-1.5 hover:bg-[#A94B4B]/10 rounded-lg" title="Excluir"><svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 text-[#A94B4B]" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button></div></div>; })}</div>}</Card>
        </>)}

        {activeTab === 'flow' && (<div className="space-y-6"><h2 className="font-display text-2xl font-bold text-[#0B1F33] flex items-center gap-2"><BarChart3 className="text-[#A9823A]" /> Fluxo Financeiro</h2><div className="grid grid-cols-1 md:grid-cols-4 gap-4"><Card className="p-5" onClick={() => { setUserFilter('all'); setActiveTab('dashboard'); }}><div className="flex items-center justify-between mb-2"><div className="flex items-center gap-2"><TrendingUp className="w-5 h-5 text-[#2F6B57]" /><p className="text-xs text-[#707780] font-medium uppercase">Receitas</p></div>{flowMetrics.incomeChange >= 0 ? <ArrowUpRight className="w-4 h-4 text-[#2F6B57]" /> : <ArrowDownRight className="w-4 h-4 text-[#A94B4B]" />}</div><p className="text-2xl font-bold text-[#0B1F33] font-display">{formatBRL(flowMetrics.income)}</p><p className={`text-xs mt-1 ${flowMetrics.incomeChange >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{flowMetrics.incomeChange >= 0 ? '+' : ''}{flowMetrics.incomeChange.toFixed(1)}% vs anterior</p><p className="text-xs text-[#2F6B57] mt-2 flex items-center gap-1">Ver lançamentos <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card><Card className="p-5" onClick={() => { setUserFilter('all'); setActiveTab('dashboard'); }}><div className="flex items-center justify-between mb-2"><div className="flex items-center gap-2"><TrendingDown className="w-5 h-5 text-[#A94B4B]" /><p className="text-xs text-[#707780] font-medium uppercase">Despesas</p></div>{flowMetrics.expensesChange <= 0 ? <ArrowDownRight className="w-4 h-4 text-[#2F6B57]" /> : <ArrowUpRight className="w-4 h-4 text-[#A94B4B]" />}</div><p className="text-2xl font-bold text-[#0B1F33] font-display">{formatBRL(flowMetrics.expenses)}</p><p className={`text-xs mt-1 ${flowMetrics.expensesChange <= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{flowMetrics.expensesChange >= 0 ? '+' : ''}{flowMetrics.expensesChange.toFixed(1)}% vs anterior</p><p className="text-xs text-[#A94B4B] mt-2 flex items-center gap-1">Ver lançamentos <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card><Card className="p-5" onClick={() => setActiveTab('investments')}><div className="flex items-center justify-between mb-2"><div className="flex items-center gap-2"><DollarSign className="w-5 h-5 text-[#A9823A]" /><p className="text-xs text-[#707780] font-medium uppercase">Aportes</p></div>{flowMetrics.contributionsChange >= 0 ? <ArrowUpRight className="w-4 h-4 text-[#2F6B57]" /> : <ArrowDownRight className="w-4 h-4 text-[#A94B4B]" />}</div><p className="text-2xl font-bold text-[#0B1F33] font-display">{formatBRL(flowMetrics.contributions)}</p><p className={`text-xs mt-1 ${flowMetrics.contributionsChange >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{flowMetrics.contributionsChange >= 0 ? '+' : ''}{flowMetrics.contributionsChange.toFixed(1)}% vs anterior</p><p className="text-xs text-[#A9823A] mt-2 flex items-center gap-1">Ver investimentos <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card><Card className="p-5" onClick={() => setActiveTab('patrimony')}><div className="flex items-center justify-between mb-2"><div className="flex items-center gap-2"><PiggyBank className="w-5 h-5 text-[#0B1F33]" /><p className="text-xs text-[#707780] font-medium uppercase">Saldo</p></div></div><p className={`text-2xl font-bold font-display ${flowMetrics.balance >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{formatBRL(flowMetrics.balance)}</p><p className="text-xs text-[#707780] mt-1">Receitas - Despesas - Aportes</p><p className="text-xs text-[#0B1F33] mt-2 flex items-center gap-1">Ver patrimônio <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></p></Card></div><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-6">Evolução Mensal</h3>{flowMetrics.history.length === 0 ? <p className="text-center py-10 text-[#707780]">Sem histórico ainda.</p> : <div className="space-y-6">{flowMetrics.history.map((item: any, idx: number) => { const bal = item.income - item.expenses - item.contributions; const mi = Math.max(...flowMetrics.history.map((h: any) => h.income)); const me = Math.max(...flowMetrics.history.map((h: any) => h.expenses)); return <div key={idx} className="space-y-3 p-4 bg-[#F7F5F0] rounded-lg"><div className="flex items-center justify-between mb-2"><span className="font-medium text-[#0B1F33] font-display">{formatMonthYear(item.month)}</span><span className={`font-bold font-display ${bal >= 0 ? 'text-[#2F6B57]' : 'text-[#A94B4B]'}`}>{formatBRL(bal)}</span></div><div className="space-y-1"><div className="flex justify-between text-xs"><span className="text-[#707780]">Receitas</span><span className="font-medium text-[#2F6B57]">{formatBRL(item.income)}</span></div><ProgressBar value={(item.income / mi) * 100} color="bg-[#2F6B57]" /></div><div className="space-y-1"><div className="flex justify-between text-xs"><span className="text-[#707780]">Despesas</span><span className="font-medium text-[#A94B4B]">{formatBRL(item.expenses)}</span></div><ProgressBar value={(item.expenses / me) * 100} color="bg-[#A94B4B]" /></div><div className="space-y-1"><div className="flex justify-between text-xs"><span className="text-[#707780]">Aportes</span><span className="font-medium text-[#A9823A]">{formatBRL(item.contributions)}</span></div><ProgressBar value={(item.contributions / mi) * 100} color="bg-[#A9823A]" /></div></div>; })}</div>}</Card></div>)}

        {activeTab === 'health' && (<div className="space-y-6"><h2 className="font-display text-2xl font-bold text-[#0B1F33] flex items-center gap-2"><Activity className="text-[#A9823A]" /> Saúde Financeira</h2><Card className={`p-6 text-center ${healthMetrics.healthStatus === 'green' ? 'bg-[#2F6B57]/5 border-[#2F6B57]/20' : healthMetrics.healthStatus === 'yellow' ? 'bg-[#B8860B]/5 border-[#B8860B]/20' : 'bg-[#A94B4B]/5 border-[#A94B4B]/20'}`}><p className="text-4xl mb-2">{healthMetrics.healthStatus === 'green' ? '🟢' : healthMetrics.healthStatus === 'yellow' ? '🟡' : '🔴'}</p><h3 className="text-2xl font-bold font-display text-[#0B1F33]">{healthMetrics.healthLabel}</h3><p className="text-[#707780] mt-1">Score: {healthMetrics.healthScore}/100</p></Card><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Card className="p-5"><h4 className="font-bold text-[#2F6B57] mb-2 flex items-center gap-1"><ArrowUpRight className="w-4 h-4" /> Pontos Fortes</h4><ul className="text-sm text-[#707780] space-y-1 list-disc pl-4">{healthMetrics.strengths.length ? healthMetrics.strengths.map((s: string, i: number) => <li key={i}>{s}</li>) : <li>Nenhum</li>}</ul></Card><Card className="p-5"><h4 className="font-bold text-[#A94B4B] mb-2 flex items-center gap-1"><ArrowDownRight className="w-4 h-4" /> Atenção</h4><ul className="text-sm text-[#707780] space-y-1 list-disc pl-4">{healthMetrics.issues.length ? healthMetrics.issues.map((s: string, i: number) => <li key={i}>{s}</li>) : <li>Tudo ok</li>}</ul></Card></div><Card className="p-5"><h3 className="font-display font-bold text-[#0B1F33] mb-4">Métricas</h3><div className="grid grid-cols-1 md:grid-cols-3 gap-4"><div className="p-4 bg-[#F7F5F0] rounded-lg"><p className="text-xs text-[#707780] mb-1">Despesas/Receita</p><p className={`text-2xl font-bold font-display ${healthMetrics.expenseRatio <= 60 ? 'text-[#2F6B57]' : healthMetrics.expenseRatio <= 80 ? 'text-[#B8860B]' : 'text-[#A94B4B]'}`}>{healthMetrics.expenseRatio.toFixed(1)}%</p><p className="text-xs text-[#707780] mt-1">Ideal: até 60%</p></div><div className="p-4 bg-[#F7F5F0] rounded-lg"><p className="text-xs text-[#707780] mb-1">Aportes/Receita</p><p className={`text-2xl font-bold font-display ${healthMetrics.investmentRatio >= 20 ? 'text-[#2F6B57]' : healthMetrics.investmentRatio >= 10 ? 'text-[#B8860B]' : 'text-[#A94B4B]'}`}>{healthMetrics.investmentRatio.toFixed(1)}%</p><p className="text-xs text-[#707780] mt-1">Ideal: 20%+</p></div><div className="p-4 bg-[#F7F5F0] rounded-lg"><p className="text-xs text-[#707780] mb-1">Dívidas/Ativos</p><p className={`text-2xl font-bold font-display ${healthMetrics.debtRatio <= 30 ? 'text-[#2F6B57]' : healthMetrics.debtRatio <= 50 ? 'text-[#B8860B]' : 'text-[#A94B4B]'}`}>{healthMetrics.debtRatio.toFixed(1)}%</p><p className="text-xs text-[#707780] mt-1">Ideal: até 30%</p></div></div></Card></div>)}

        {activeTab === 'goals' && (<div className="space-y-4"><div className="flex items-center gap-3 mb-6"><Target className="w-6 h-6 text-[#A9823A]" /><h2 className="font-display text-2xl font-bold text-[#0B1F33]">Nossos Sonhos</h2></div>{goalsWithProgress.length === 0 ? <div className="flex flex-col items-center justify-center text-center py-20 bg-white rounded-xl border border-dashed border-[#0B1F33]/20"><Target className="w-16 h-16 text-[#0B1F33]/10 mb-4" /><p className="text-[#707780] mb-6 text-lg">Nenhum sonho cadastrado.</p><button onClick={() => setIsDrawerOpen(true)} className="bg-[#A9823A] hover:bg-[#8c6b2e] text-white font-semibold px-6 py-3 rounded-lg flex items-center gap-2"><Plus className="w-5 h-5" /> Cadastrar meta</button></div> : goalsWithProgress.map((goal: any) => { const sd = new Date(goal.start_date || new Date()); const ed = goal.end_date ? new Date(goal.end_date) : null; const td = new Date(); let dt = "Sem prazo"; let dl = 0; let pt = 0; if (ed) { const tot = Math.ceil(Math.abs(ed.getTime() - sd.getTime()) / 86400000) || 1; dl = Math.ceil(Math.abs(ed.getTime() - td.getTime()) / 86400000); const dp = Math.ceil(Math.abs(td.getTime() - sd.getTime()) / 86400000); pt = Math.min(100, Math.max(0, (dp / tot) * 100)); dt = td > ed ? "Encerrado" : `${dl} dias`; } return <Card key={goal.id} className="p-6 relative overflow-hidden">{ed && <div className="absolute top-0 left-0 w-full h-1.5 bg-[#F7F5F0]"><div className="h-full bg-[#A9823A]" style={{ width: `${pt}%` }} /></div>}<div className="flex items-start justify-between mb-4 mt-2"><div><h3 className="font-display text-xl font-bold text-[#0B1F33]">{goal.title}</h3><div className="flex items-center gap-2 mt-1 text-xs text-[#707780]"><span>Início: {formatDateBR(goal.start_date)}</span>{ed && <><span>•</span><span>Fim: {formatDateBR(goal.end_date)}</span></>}</div></div><div className="text-right"><p className="text-2xl font-bold text-[#0B1F33] font-display">{formatBRL(goal.totalAcumulado)}</p><Badge variant="gold">{goal.percentage.toFixed(1)}%</Badge></div></div><div className="mb-4"><div className="flex justify-between text-xs text-[#707780] mb-1"><span>Progresso</span><span>Meta: {formatBRL(goal.target_amount)}</span></div><ProgressBar value={goal.percentage} color="bg-[#0B1F33]" /></div><div className="flex justify-between items-end mt-4 pt-4 border-t border-[#0B1F33]/10"><div className="text-sm text-[#707780]">{ed && <p className={`font-medium ${dl < 30 && dl > 0 ? 'text-[#A94B4B]' : 'text-[#2F6B57]'}`}>⏳ {dt}</p>}<p className="mt-1">Faltam <span className="font-semibold text-[#0B1F33]">{formatBRL(goal.remaining)}</span></p></div><div className="flex gap-2"><div className="bg-[#0B1F33]/5 px-3 py-1.5 rounded text-xs text-center"><p className="text-[#707780]">Aportes</p><p className="font-bold text-[#0B1F33]">{formatBRL(goal.totalAportes)}</p></div><div className="bg-[#A9823A]/5 px-3 py-1.5 rounded text-xs text-center"><p className="text-[#707780]">Rendimentos</p><p className="font-bold text-[#A9823A]">{formatBRL(goal.totalRendimentos)}</p></div></div></div></Card>; })}</div>)}

        {activeTab === 'investments' && (<div className="space-y-4"><h2 className="font-display text-2xl font-bold text-[#0B1F33] flex items-center gap-2"><Briefcase className="text-[#A9823A]" /> Investimentos</h2><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Card className="p-6"><div className="grid grid-cols-2 gap-4 mb-6"><div className="bg-[#0B1F33]/5 p-5 rounded-lg"><p className="text-sm text-[#707780]">Total Aportado</p><p className="text-3xl font-bold text-[#0B1F33] mt-2 font-display">{formatBRL(metrics.totalAportes)}</p></div><div className="bg-[#A9823A]/5 p-5 rounded-lg"><p className="text-sm text-[#707780]">Rendimentos</p><p className="text-3xl font-bold text-[#A9823A] mt-2 font-display">{formatBRL(metrics.monthlyYield || 0)}</p><p className="text-xs text-[#A9823A] mt-2 font-medium">{metrics.totalAportes > 0 ? `+${((metrics.monthlyYield || 0) / metrics.totalAportes * 100).toFixed(2)}%` : 'Sem aportes'}</p></div></div><h3 className="font-display font-bold text-[#0B1F33] mb-3">Distribuição</h3><div className="space-y-2">{[{ name: 'Ações', value: metrics.investmentTotals.acoes, color: 'bg-[#0B1F33]' }, { name: 'FIIs', value: metrics.investmentTotals.fiis, color: 'bg-[#A9823A]' }, { name: 'Dólar', value: metrics.investmentTotals.dolar, color: 'bg-[#2F6B57]', isUSD: true }].map((item: any) => <div key={item.name} className="flex justify-between items-center p-3 bg-[#F7F5F0] rounded-lg"><div className="flex items-center gap-2"><div className={`w-2 h-2 rounded-full ${item.color}`} /><span className="text-sm font-medium text-[#0B1F33]">{item.name}</span></div><span className="font-bold text-[#0B1F33] font-display">{item.isUSD ? formatUSD(item.value) : formatBRL(item.value)}</span></div>)}</div></Card><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-4">📊 Distribuição Visual</h3>{metrics.totalAportes > 0 ? <InvestmentPieChart acoes={metrics.investmentTotals.acoes} fiis={metrics.investmentTotals.fiis} dolar={metrics.investmentTotals.dolar} /> : <div className="flex flex-col items-center justify-center py-12 text-[#707780]"><Briefcase className="w-12 h-12 text-[#0B1F33]/10 mb-3" /><p className="text-sm">Sem investimentos neste mês</p></div>}</Card></div></div>)}

        {activeTab === 'patrimony' && (<div className="space-y-4"><div className="flex justify-between items-center"><h2 className="font-display text-2xl font-bold text-[#0B1F33] flex items-center gap-2"><PiggyBank className="text-[#A9823A]" /> Patrimônio Líquido</h2><div className="flex bg-white p-1 rounded-lg border border-[#0B1F33]/10">{(['family', 'Felipe', 'Camila'] as const).map((v) => <button key={v} onClick={() => setPatrimonyView(v)} className={`px-3 py-1 text-xs rounded-md ${patrimonyView === v ? 'bg-[#0B1F33] text-white' : 'text-[#707780]'}`}>{v === 'family' ? 'Família' : v}</button>)}</div></div><Card className="p-6 card-gold text-center"><p className="text-[#C5A45A] text-sm uppercase tracking-wider">Patrimônio Líquido</p><p className="text-4xl font-bold font-display mt-2">{formatBRL(patrimonyMetrics.netPatrimony)}</p><div className="flex justify-center gap-8 mt-6 text-sm"><div><p className="text-white/60">Ativos</p><p className="font-bold">{formatBRL(patrimonyMetrics.totalAssets)}</p></div><div><p className="text-white/60">Passivos</p><p className="font-bold">{formatBRL(patrimonyMetrics.totalLiabilities)}</p></div></div></Card><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-4">Evolução Patrimonial</h3><div className="space-y-3">{patrimonyHistory.map((item: any) => { const mp = Math.max(...patrimonyHistory.map((h: any) => h.net_patrimony)); return <div key={item.id} className="space-y-1"><div className="flex justify-between text-sm"><span className="font-medium text-[#0B1F33]">{formatMonthYear(item.month)}</span><span className="font-bold text-[#0B1F33] font-display">{formatBRL(item.net_patrimony)}</span></div><ProgressBar value={(item.net_patrimony / mp) * 100} color="bg-[#0B1F33]" /></div>; })}</div></Card><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-4">Ativos</h3><div className="space-y-2">{assets.filter((a: any) => patrimonyView === 'family' || a.owner === patrimonyView || a.owner === 'família').map((asset: any) => <div key={asset.id} className="flex justify-between items-center p-3 bg-[#F7F5F0] rounded-lg"><div><p className="text-sm font-medium text-[#0B1F33]">{asset.name}</p><p className="text-xs text-[#707780]">{asset.owner}</p></div><span className="font-bold text-[#2F6B57] font-display">{formatBRL(asset.value)}</span></div>)}</div></Card><Card className="p-6"><h3 className="font-display font-bold text-[#0B1F33] mb-4">Passivos</h3><div className="space-y-2">{liabilities.filter((l: any) => patrimonyView === 'family' || l.owner === patrimonyView || l.owner === 'família').map((liability: any) => <div key={liability.id} className="flex justify-between items-center p-3 bg-[#A94B4B]/5 rounded-lg"><div><p className="text-sm font-medium text-[#0B1F33]">{liability.name}</p><p className="text-xs text-[#707780]">{liability.owner}</p></div><span className="font-bold text-[#A94B4B] font-display">{formatBRL(liability.value)}</span></div>)}</div></Card></div></div>)}

        {activeTab === 'news' && (<div className="space-y-6"><div className="flex items-center gap-3 mb-2"><Newspaper className="w-6 h-6 text-[#A9823A]" /><h2 className="font-display text-2xl font-bold text-[#0B1F33]">Notícias do Mercado</h2></div><div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">{[{ id: 'all', label: 'Todas' }, { id: 'infomoney', label: 'InfoMoney' }, { id: 'investing', label: 'Investing.com' }, { id: 'investopedia', label: 'Investopedia' }, { id: 'valor', label: 'Valor Econômico' }, { id: 'moneytimes', label: 'Money Times' }].map((f) => <button key={f.id} onClick={() => setNewsSource(f.id)} className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all ${newsSource === f.id ? 'bg-[#0B1F33] text-white shadow-md' : 'bg-white text-[#707780] hover:bg-[#0B1F33]/5 border border-[#0B1F33]/10'}`}>{f.label}</button>)}</div>{newsLoading ? <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{[...Array(6)].map((_, i) => <NewsCardSkeleton key={i} />)}</div> : news.length === 0 ? <div className="text-center py-16 bg-white rounded-xl border border-dashed border-[#0B1F33]/20"><Newspaper className="w-16 h-16 text-[#0B1F33]/10 mx-auto mb-4" /><p className="text-[#707780] text-lg">Nenhuma notícia</p><button onClick={() => fetchNews(newsSource)} className="mt-4 text-[#A9823A] font-medium hover:underline">Tentar novamente</button></div> : <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{news.map((item: any) => <NewsCard key={item.id} news={item} />)}</div>}</div>)}
      </main>

      <button onClick={() => setIsDrawerOpen(true)} className="fixed bottom-6 right-6 w-14 h-14 bg-[#0B1F33] hover:bg-[#172a3d] text-[#C5A45A] rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-105 active:scale-95 z-40 border border-[#A9823A]/30"><Plus className="w-8 h-8" /></button>

      {isDrawerOpen && (<div className="fixed inset-0 z-50 bg-[#0B1F33]/50 backdrop-blur-sm flex justify-end" onClick={() => setIsDrawerOpen(false)}><div className="w-full max-w-md bg-white h-full shadow-2xl overflow-y-auto" onClick={(e) => e.stopPropagation()}><div className="sticky top-0 bg-white flex items-center justify-between border-b border-[#0B1F33]/10 p-4 z-10"><h2 className="font-display text-lg font-bold text-[#0B1F33]">{activeTab === 'goals' ? 'Nova Meta' : editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}</h2><button onClick={() => setIsDrawerOpen(false)} className="p-1 hover:bg-[#F7F5F0] rounded"><X className="w-5 h-5 text-[#707780]" /></button></div><div className="p-6">{activeTab === 'goals' ? <form onSubmit={handleAddGoal} className="space-y-5"><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Nome da Meta</label><input type="text" required value={formData.goal_title} onChange={(e) => setFormData({ ...formData, goal_title: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" placeholder="Ex: Nossa Casa" /></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Valor (R$)</label><input type="number" step="0.01" required value={formData.goal_target} onChange={(e) => setFormData({ ...formData, goal_target: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" placeholder="500000" /></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Início</label><input type="date" required value={formData.goal_start} onChange={(e) => setFormData({ ...formData, goal_start: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" /></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Término</label><input type="date" value={formData.goal_end} onChange={(e) => setFormData({ ...formData, goal_end: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" /></div></div><button type="submit" className="w-full bg-[#A9823A] hover:bg-[#8c6b2e] text-white font-semibold py-4 rounded-lg mt-6">Criar Meta</button></form> : <form onSubmit={editingTransaction ? handleUpdateTransaction : handleAddTransaction} className="space-y-5"><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Quem Lançou</label><select value={formData.created_by} onChange={(e) => setFormData({ ...formData, created_by: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]"><option value="Felipe">Felipe</option><option value="Camila">Camila</option></select></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Tipo</label><select value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value, category_id: '' })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]"><option value="receita">Receita</option><option value="despesa_fixa">Despesa Fixa</option><option value="despesa_variavel">Despesa Variável</option><option value="investimento">Investimento</option><option value="reserva">Reserva</option></select></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Categoria</label><select value={formData.category_id} onChange={(e) => setFormData({ ...formData, category_id: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]"><option value="">Selecione...</option>{availableCategories.map((c: any) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Valor (R$)</label><input type="number" step="0.01" required value={formData.amount} onChange={(e) => setFormData({ ...formData, amount: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" placeholder="0,00" /></div><div className="space-y-2"><label className="text-sm font-medium text-[#0B1F33]">Data</label><input type="date" required value={formData.date} onChange={(e) => setFormData({ ...formData, date: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" /></div><div className="space-y-2"><div className="flex justify-between items-center"><label className="text-sm font-medium text-[#0B1F33]">Descrição</label><button type="button" onClick={startVoiceRecognition} disabled={isListening} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold ${isListening ? 'bg-red-100 text-red-600 animate-pulse border border-red-200' : 'bg-[#A9823A]/10 text-[#A9823A] hover:bg-[#A9823A]/20 border border-[#A9823A]/20'}`}>{isListening ? <><span className="w-2 h-2 bg-red-500 rounded-full animate-ping" />Ouvindo...</> : <>🎙 Falar</>}</button></div><input type="text" value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-4 py-3 text-sm bg-[#F7F5F0]" placeholder="Ex: Compras do mês" />{voiceTranscript && <p className="text-xs text-[#707780] italic bg-[#F7F5F0] p-2 rounded border border-dashed border-[#0B1F33]/10">"{voiceTranscript}"</p>}</div><div className="space-y-3 p-4 bg-[#A9823A]/5 rounded-lg border border-[#A9823A]/20"><label className="flex items-center gap-2 cursor-pointer"><input type="checkbox" checked={formData.is_recurring || false} onChange={(e) => setFormData({ ...formData, is_recurring: e.target.checked })} className="w-4 h-4 rounded border-[#0B1F33]/20 text-[#A9823A]" /><span className="text-sm font-medium text-[#0B1F33]">🔄 Recorrente</span></label>{formData.is_recurring && <div className="grid grid-cols-2 gap-3 mt-2"><div><label className="text-xs text-[#707780] block mb-1">Dia do mês</label><input type="number" min="1" max="31" value={formData.recurring_day || ''} onChange={(e) => setFormData({ ...formData, recurring_day: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-3 py-2 text-sm bg-white" placeholder="10" /></div><div><label className="text-xs text-[#707780] block mb-1">Até quando?</label><input type="date" value={formData.recurring_end_date || ''} onChange={(e) => setFormData({ ...formData, recurring_end_date: e.target.value })} className="w-full rounded-lg border border-[#0B1F33]/20 px-3 py-2 text-sm bg-white" /></div></div>}</div>{editingTransaction ? <div className="flex gap-3 mt-6"><button type="button" onClick={() => { setEditingTransaction(null); setIsDrawerOpen(false); }} className="flex-1 bg-[#F7F5F0] text-[#0B1F33] font-semibold py-4 rounded-lg border border-[#0B1F33]/10">Cancelar</button><button type="submit" className="flex-1 bg-[#0B1F33] hover:bg-[#172a3d] text-white font-semibold py-4 rounded-lg">Salvar</button></div> : formData.is_recurring ? <button type="button" onClick={handleCreateRecurring} className="w-full bg-[#A9823A] hover:bg-[#8c6b2e] text-white font-semibold py-4 rounded-lg mt-6">🔄 Criar Recorrência</button> : <button type="submit" className="w-full bg-[#0B1F33] hover:bg-[#172a3d] text-white font-semibold py-4 rounded-lg mt-6">Salvar Lançamento</button>}</form>}</div></div></div>)}
    </div>
  );
}